1: import { mkdtempSync, rmSync } from "node:fs";
2: import { tmpdir } from "node:os";
3: import { join } from "node:path";
4: import { afterAll } from "vitest";
5: 
6: // Keep tests from reading or mutating the developer's real ~/.cast. Individual
7: // tests may temporarily point HOME at a narrower fixture and restore this one.
8: const originalHome = process.env.HOME;
9: const testHome = mkdtempSync(join(tmpdir(), "cast-vitest-home-"));
10: process.env.HOME = testHome;
11: 
12: afterAll(() => {
13: 	process.env.HOME = originalHome;
14: 	rmSync(testHome, { recursive: true, force: true });
15: });
16:

